content.content:
4ed1d45 Switch the site to the new promo video and refine the demo gate
      overflow-x: hidden;
    }
    img, video, svg { display: block; max-width: 100%; }
    a { color: inherit; }
    p { margin: 0; }
    h1, h2, h3 { margin: 0; font-weight: 800; letter-spacing: -.03em; line-height: 1.05; text-wrap: balance; }
    :focus-visible { outline: 3px solid var(--blue); outline-offset: 3px; border-radius: 6px; }
    .wrap { width: min(1120px, 100% - 2 * var(--gutter)); margin-inline: auto; }
    .sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

    /* ---------- the annotation layer ---------- */
    [data-ink] { position: relative; }
    .ink {
      position: absolute; inset: 0; width: 100%; height: 100%;
      overflow: visible; pointer-events: none; z-index: 3;
    }
    .ink .red { stroke: var(--red); fill: none; }
    .ink .blue { stroke: var(--blue); fill: none; }
    .ink .head.red { fill: var(--red); stroke: none; }
    .ink .head.blue { fill: var(--blue); stroke: none; }
    .ink .handle { fill: #fff; stroke: var(--red); stroke-width: 2; }
    .ink .s {
      stroke-dasharray: var(--len);
      stroke-dashoffset: var(--len);
      transition: stroke-dashoffset .55s cubic-bezier(.55, 0, .25, 1) var(--delay, 0s);
    }
    .is-drawn .ink .s { stroke-dashoffset: 0; }
    .ink .pop, .js [data-ink] .badge, .js [data-ink] .note {
      transform-box: fill-box; transform-origin: center;
      transition: transform .38s cubic-bezier(.3, 1.5, .5, 1) var(--delay, 0s), opacity .25s linear var(--delay, 0s);
    }
    .ink .pop, .js [data-ink]:not(.is-drawn) .badge { transform: scale(0); }
    .js [data-ink]:not(.is-drawn) .note { opacity: 0; transform: translateY(6px); }
    .is-drawn .ink .pop { transform: none; }
    @media (prefers-reduced-motion: reduce) {
      .ink .s { stroke-dashoffset: 0; transition: none; }
      .ink .pop, .js [data-ink]:not(.is-drawn) .badge, .js [data-ink]:not(.is-drawn) .note { transform: none; opacity: 1; transition: none; }
    }

    /* Skryn's own marks, as HTML */
    .badge {
      display: inline-grid; place-items: center; flex: none;
      width: 32px; height: 32px; border-radius: 50%;
      background: var(--red); color: #fff;
      font: 700 18px/1 var(--sans); letter-spacing: -.02em;
      font-variant-numeric: tabular-nums;
      width: min(1040px, 100% - 2 * var(--gutter)); margin: 0 auto;
      display: flex; justify-content: flex-end; align-items: center; gap: 12px 24px; flex-wrap: wrap;
      font-size: 15px;
    }
    .stage-cap.above { margin-bottom: 22px; }
    /* below: the switch link centered under the frame, the video's Esc hint on the right */
    .stage-cap.below { margin-top: 22px; display: grid; grid-template-columns: 1fr auto 1fr; }
    .stage-cap.below .switch { grid-column: 2; }
    .stage-cap.below .v-only { grid-column: 3; justify-self: end; }
    /* modes: the video by default; .pg-mode swaps in the playground, .gated puts Skryn's blur over it */
    .stage .pg-win, .stage .gate, .stage .pg-bar, .stage .switch { display: none; }
    .stage.pg-mode video, .stage.pg-mode .play, .stage.pg-mode .v-only, .stage.pg-mode .crop-frame > .h { display: none; }
    .stage.pg-mode .pg-win { display: block; }
    .stage.pg-mode.gated .gate { display: grid; }
    .stage.pg-mode .pg-bar { display: flex; }
    .stage.can-play .switch { display: inline-block; }
    /* while gated, the bar and the link hold their space, so the section (and its backdrop) keeps its size when the blur opens */
    .stage .pg-bar, .stage .switch { transition: opacity .3s ease; }
    .stage.gated .pg-bar, .stage.gated .switch { visibility: hidden; opacity: 0; }
    .stage.pg-mode .crop-frame { outline: 0; border-radius: 12px; }
    .switch {
      border: 0; padding: 6px 2px; background: none; cursor: pointer;
      font: 600 15px/1.2 var(--sans); color: #1d1d1f; text-decoration: underline; text-underline-offset: 3px;
    }
    .switch:hover { opacity: .75; }

    /* the playground: a browser replica of Skryn's annotation window */
    .pg-win {
      position: relative; aspect-ratio: 872 / 543; border-radius: 12px; overflow: hidden; background: #fff;
      user-select: none; -webkit-user-select: none; outline: none;
    }
    .pg-win:focus-visible { box-shadow: 0 0 0 2px rgba(255, 255, 255, .7); }
    .pg-win img { width: 100%; height: 100%; object-fit: cover; pointer-events: none; }
    .pg-win canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
    .pg-win textarea {
      position: absolute; margin: 0; padding: 0; border: 0; resize: none; overflow: hidden; background: transparent;
      font-family: var(--sans); font-weight: 700; line-height: 1.2; white-space: pre-wrap; overflow-wrap: break-word;
      outline: 1px dashed rgba(0, 0, 0, .28); outline-offset: 2px; border-radius: 0; user-select: text; -webkit-user-select: text;
    }
    .pg-toast {
      position: absolute; left: 50%; bottom: 14px; z-index: 3; display: inline-flex; align-items: center; gap: 8px;
      max-width: calc(100% - 24px); padding: 7px 12px 7px 8px; border-radius: 12px;
      background: rgba(22, 22, 26, .94); color: #f3f3f5; font: 600 13px/1.3 var(--sans);
