content.content:
.top nav .nav-dl { padding: 7px 14px; border-radius: 999px; background: var(--ink); color: var(--paper); font-weight: 600; font-size: 14px; }
.top nav .nav-dl:hover { color: var(--paper); opacity: .88; }
.top nav a { text-decoration: none; }
.top nav a:hover { color: var(--ink); }
@media (max-width: 620px) { .top nav a:not(.gh):not(.nav-dl) { display: none; } }

/* ---------- hero ---------- */
.hero { padding: clamp(24px, 6vw, 72px) 0 clamp(48px, 8vw, 96px); }
.hero h1 {
  /* by width, and by height so the whole hero fits a laptop screen: 3.12 lines of headline + ~410px of the rest */
  --fs: clamp(50px, min(11.2vw, 32vh - 132px), 160px);
  font-size: var(--fs);
  line-height: 1.04; letter-spacing: -.045em;
}
.hero h1 > span { display: block; }
.hero h1 .circled { display: inline-block; white-space: nowrap; }
.hero h1 .tag { margin-left: calc(var(--fs) * .28); vertical-align: .5em; letter-spacing: 0; }
/* no room beside the lines on phones: each tag goes under its line */
@media (max-width: 599px) { .hero h1 .tag { display: flex; width: max-content; margin: 8px 0 16px; vertical-align: 0; } }

.lede { max-width: 36em; margin-top: clamp(24px, 3vw, 36px); font-size: clamp(18px, 1.9vw, 21px); color: var(--muted); line-height: 1.5; }
.lede strong { color: var(--ink); font-weight: 600; }
.cta-row { display: grid; grid-template-columns: auto auto; justify-content: start; justify-items: start; align-items: center; gap: 14px clamp(48px, 7.5vw, 110px); margin-top: 68px; }
.download {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 15px 26px; border-radius: 12px;
  background: var(--ink); color: var(--paper);
  font-weight: 700; font-size: 17px; text-decoration: none; letter-spacing: -.01em;
  transition: transform .15s ease;
}
.download:hover { transform: translateY(-1px); }
.download svg { width: 18px; height: 18px; }
.start { display: flex; align-items: center; gap: 22px; }
.start .note { font-size: 24px; }
.keys.legend { display: inline-grid; grid-template-columns: auto auto; gap: 5px 8px; padding: 6px 12px 6px 6px; }
.keys.legend > span { display: flex; justify-content: flex-end; gap: 4px; }
.keys.legend b { margin-left: 0; align-self: center; }
.keys.legend b + span { margin-left: 0; }
@media (max-width: 719px) {
  .cta-row { grid-template-columns: 1fr; margin-top: 36px; }
