REDACTED; cat > $S/shot.mjs <<'EOF'
import { chromium } from 'playwright-core';
const [,, tag = 'shot', ...sizes] = process.argv;
const browser = await chromium.launch({ executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome' });
for (const sz of (sizes.length ? sizes : ['1000x650', '1440x900', '1280x720'])) {
  const [w, h] = sz.split('x').map(Number);
  const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 2 });
  await page.goto('http://localhost:8765/');
  await page.waitForTimeout(800);
  await page.evaluate(() => document.getElementById('demo').scrollIntoView());
  await page.waitForTimeout(2500);
  const info = await page.evaluate(() => {
    const g = document.querySelector('.gate').getBoundingClientRect();
    const r = (s) => { const e = document.querySelector(s); if (!e) return null; const b = e.getBoundingClientRect(); return [Math.round(b.top), Math.round(b.bottom)]; };
    return { gate: [Math.round(g.top), Math.round(g.bottom), Math.round(g.width)], cap: r('.gate-cap'), note: r('.gate-note'), more: r('.gate-more'), vh: innerHeight };
  });
  console.log(sz, JSON.stringify(info));
  await page.screenshot({ path: `${process.env.S}/${tag}-${sz}.png` });
  await page.close();
}
await browser.close();
EOF
cd $S && S=$S node shot.mjs before

